-- Patient Safety & Quality Improvement: Part 5 (Questions 201-250)
-- US MD / MBBS / USMLE Step 3
-- Target: Supabase (PostgreSQL)
-- Topic Slug: ethics-patient-safety

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ethics-patient-safety' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ethics-patient-safety not found.';
    END IF;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    -- MEDICATION RECONCILIATION
    (v_topic_id, 'At which point in the care continuum is medication reconciliation MOST critical for preventing errors?', '["Every 4 hours during the hospital stay", "At every transition of care (admission, transfer, and discharge)", "Only when the patient requests it", "Once a year during a physical"]', 1, 'Transitions are high-risk periods where information is often lost or misinterpreted. Reconciliation at each transition is a National Patient Safety Goal.'),
    (v_topic_id, 'Which of the following is the primary goal of "Medication Reconciliation"?', '["To find the cheapest version of a drug", "To ensure the patient has an accurate and complete list of medications across all settings", "To reduce the number of medications a patient takes", "To increase the pharmacy''s profit"]', 1, 'The goal is to avoid omissions, duplications, dosing errors, and drug interactions.'),
    (v_topic_id, 'What is the "Best Possible Medication History" (BPMH)?', '["The list provided by the patient''s insurance company", "A comprehensive history obtained by using at least two sources (e.g., patient interview + pharmacy records)", "The list found in the patient''s most recent clinic note", "A list of only the patient''s expensive drugs"]', 1, 'BPMH is a systematic process that uses multiple sources to verify what the patient is actually taking at home.'),
    (v_topic_id, 'A common error during hospital discharge is the failure to:', '["Tell the patient the name of their nurse", "Reconcile pre-hospital medications with new hospital-started medications", "Give the patient a hospital gown to take home", "Collect the patient''s co-pay"]', 1, 'Patients often leave with conflicting orders (e.g., taking both their home diuretic and a new hospital-prescribed diuretic), leading to harm.'),
    (v_topic_id, 'Which professional is often considered the "expert" leader in medication reconciliation in many high-performing systems?', '["Hospital Administrator", "Pharmacist", "Phlebotomist", "Physical Therapist"]', 1, 'Pharmacists and pharmacy technicians are specifically trained to identify medication discrepancies and improve reconciliation accuracy.'),

    -- HIGH-ALERT MEDICATIONS & TECH
    (v_topic_id, 'Which of the following classes of medications is considered "High-Alert"?', '["Anticoagulants (e.g., Heparin, Warfarin)", "Insulin", "Intravenous concentrated electrolytes (e.g., Potassium Chloride)", "All of the above"]', 3, 'High-alert medications are those that bear a heightened risk of causing significant patient harm when they are used in error.'),
    (v_topic_id, 'A "Smart Pump" prevents medication errors primarily by:', '["Administering the drug faster", "Using \"Drug Libraries\" and \"Guardrails\" to prevent infusion of doses outside of safe limits", "Reducing the cost of the infusion", "Automatically ordering the next dose from the pharmacy"]', 1, 'Smart pumps use software to prevent "typo" errors (e.g., entering 100 mL/hr instead of 10 mL/hr).'),
    (v_topic_id, 'What is a "Hard Limit" (Hard Guardrail) in a smart infusion pump?', '["A warning that the nurse can override", "A programmed limit that prevents the pump from starting if the dose is outside of a pre-set safe range", "A physical lock on the pump", "A limit on how many patients a nurse can have"]', 1, 'Hard limits cannot be bypassed, providing a forcing function for safety.'),
    (v_topic_id, 'The use of "Bar-Code Medication Administration" (BCMA) is designed to verify the:', '["Five Rights (Right patient, drug, dose, route, and time)", "Patient''s insurance status", "Manufacturer of the drug", "Cost of the medication"]', 0, 'BCMA ensures that the medication being scanned matches the patient being scanned and the order in the system.'),
    (v_topic_id, 'If a nurse bypasses a barcode scan by manually typing in the patient ID (a "work-around"), what is the most likely reason?', '["The nurse is lazy", "The system or hardware is flawed (e.g., unreadable barcodes, dead scanner batteries)", "The nurse wants to cause an error", "The doctor told them to"]', 1, 'Most work-arounds are "at-risk behaviors" driven by system failures that make the safe way difficult to follow.'),

    -- LOOK-ALIKE/SOUND-ALIKE (LASA)
    (v_topic_id, 'Which of the following is a strategy to reduce errors with "Sound-Alike" medications (e.g., Zantac vs. Zyrtec)?', '["Using only brand names", "The \"Read-Back\" of verbal or telephone orders", "Asking the patient which one they want", "Storing them right next to each other on the shelf"]', 1, 'Verifying verbal orders by writing them down and reading them back is a key safety requirement.'),
    (v_topic_id, 'Which of the following is an example of "Tall Man Lettering"?', '["prednisone", "PREDNISONE", "predniSONE", "vinBLAStine vs. vinCRIStine"]', 3, 'Tall Man lettering uses uppercase letters to distinguish similar-looking drug names.'),
    (v_topic_id, 'Standardizing medication concentrations (e.g., only stocking one concentration of Heparin in the ICU) is an example of:', '["Simplification", "Redundancy", "Forcing function", "Education"]', 0, 'Simplification reduces the number of choices and the complexity of the task, thereby reducing error risk.'),
    (v_topic_id, 'What is the "Best Practice" for storing concentrated potassium chloride in a hospital?', '["In the patient''s bedside drawer", "In a large bin in the hallway", "Only in the pharmacy (never on the patient floor in concentrated vials)", "Right next to the saline vials"]', 2, 'Concentrated potassium should not be available as a vial on clinical units to prevent accidental undiluted injection, which is fatal.'),
    (v_topic_id, 'A "Unit Dose" medication system improves safety by:', '["Delivering medications in pre-packaged, patient-specific, ready-to-administer doses", "Requiring the nurse to crush every pill", "Increasing the volume of medication stored on the unit", "Reducing the need for pharmacy oversight"]', 0, 'Unit dose systems reduce the need for complex calculations and preparation by the nursing staff.'),

    -- TRANSITIONS OF CARE & HANDOFFS
    (v_topic_id, 'What percentage of serious medical errors are estimated to be related to communication failures during handoffs?', '["10%", "30%", "50%", "Over 80%"]', 3, 'The Joint Commission consistently identifies communication failures as a leading root cause of sentinel events.'),
    (v_topic_id, 'The "I-PASS" mnemonic for clinical handoffs stands for:', '["Identification, Patient, Assessment, Situation, Summary", "Illness severity, Patient summary, Action list, Situation awareness, Synthesis", "Introduction, Plan, Allergies, Safety, Sign-off", "Important, Patient, Always, Stay, Safe"]', 1, 'I-PASS is an evidence-based, standardized handoff framework that has been shown to significantly reduce medical errors.'),
    (v_topic_id, 'In the I-PASS system, "Situation Awareness and Contingency Planning" refers to:', '["Knowing where the cafeteria is", "Discussing \"what might happen\" and the plan for the patient (e.g., \"if X happens, then do Y\")", "Asking the patient if they are aware of their situation", "Checking the weather for the next shift"]', 1, 'Contingency planning empowers the receiving team to manage complications without delay.'),
    (v_topic_id, 'A "Warm Handoff" in healthcare refers to:', '["A handoff that occurs in a heated room", "A handoff that occurs in person with the patient present (Bedside Handoff)", "A handoff that only happens via email", "A handoff that takes less than 10 seconds"]', 1, 'Bedside handoffs increase patient involvement and allow for direct verification of the patient and their equipment.'),
    (v_topic_id, 'The primary goal of a clinical "Handoff" (Handover) is:', '["To finish the shift as fast as possible", "The accurate and reliable transfer of information and responsibility for a patient", "To tell stories about difficult patients", "To assign blame for the day''s events"]', 1, 'Accurate information transfer is the core of a safe handoff.'),

    -- CARE COORDINATION & TEAMWORK
    (v_topic_id, 'Which of the following is a characteristic of a "High-Functioning Team"?', '["Clear roles and responsibilities", "Shared mental model of the plan", "Mutual support and back-up behavior", "All of the above"]', 3, 'Teamwork training (like TeamSTEPPS) focuses on these core competencies to improve safety.'),
    (v_topic_id, '"Closed-Loop Communication" is most critical during which type of event?', '["A routine physical exam", "A \"Code Blue\" or emergency resuscitation", "Writing a research paper", "Scheduling a follow-up appointment"]', 1, 'In high-stress, fast-paced environments, verifying that a verbal command was heard and performed is essential to prevent omissions or errors.'),
    (v_topic_id, 'In the SBAR communication tool, the "B" (Background) should include:', '["The patient''s childhood history", "Relevant clinical information such as admission diagnosis, current medications, and allergies", "The nurse''s opinion on the hospital food", "The patient''s insurance provider"]', 1, 'Background provides the necessary clinical context for the current situation.'),
    (v_topic_id, 'The "Two-Challenge Rule" is intended to:', '["Challenge the patient twice", "Empower all team members to voice a safety concern twice if they feel it is not being addressed", "Require two doctors to agree on every order", "Make the job twice as hard"]', 1, 'It is a tool for "graded assertiveness" to ensure that safety concerns are not ignored due to hierarchy.'),
    (v_topic_id, 'What is "Deference to Expertise" in a high-reliability organization?', '["Always listening to the oldest person in the room", "Recognizing that the person with the most relevant knowledge for the situation (regardless of rank) should lead", "Ignoring all hospital rules", "Only listening to the CEO"]', 1, 'In a crisis, the person who knows the most about the specific problem (e.g., a respiratory therapist during a ventilator alarm) should be empowered to lead.'),

    -- PATIENT INVOLVEMENT
    (v_topic_id, 'Why is patient engagement considered a critical "Safety Barrier"?', '["Patients are never wrong", "Patients and families can often detect errors or changes in condition before staff do", "It reduces the amount of work for nurses", "It is required by the insurance company"]', 1, 'Patients are the only ones present through the entire care journey and can provide a vital "safety check."'),
    (v_topic_id, 'The "Speak Up" campaign encourages patients to:', '["Talk louder", "Ask questions and voice concerns about their care and safety", "Complain about the bill", "Speak only when spoken to"]', 1, 'Empowering patients to be safety partners is a major goal of patient-centered care.'),
    (v_topic_id, 'Which of the following is a "Health Literacy" strategy for providing discharge instructions?', '["Using complex medical terminology to sound professional", "Using the \"Teach-Back\" method (asking the patient to explain the plan in their own words)", "Giving the patient a 50-page manual", "Providing instructions only in English"]', 1, 'Teach-back is the "gold standard" for ensuring patient understanding.'),
    (v_topic_id, 'A patient who does not understand how to take their new heart failure medication at home is at high risk for:', '["A medication-related readmission", "An adverse drug event", "Both A and B", "Neither"]', 2, 'Poor transition planning is a major driver of post-discharge complications.'),
    (v_topic_id, 'Discharge instructions should ideally be provided:', '["In writing and verbally", "Using plain language (avoiding jargon)", "With the inclusion of family/caregivers", "All of the above"]', 3, 'Comprehensive communication is required to bridge the gap between hospital and home.'),

    -- MISC MEDICATION SAFETY
    (v_topic_id, 'Which of the following is a common "Active Failure" in medication administration?', '["Lack of a barcode system", "A nurse misidentifying a patient", "Similar drug packaging on the shelf", "Inadequate staffing levels"]', 1, 'Misidentification is an error at the "sharp end" (direct contact).'),
    (v_topic_id, 'The "Five Rights" of medication administration are:', '["Patient, Drug, Dose, Route, Time", "Patient, Cost, Pharmacy, Doctor, Date", "Drug, Bottle, Label, Shelf, Price", "Right, Left, Up, Down, Center"]', 0, 'While necessary, the five rights are a "weak" intervention because they rely on human vigilance alone.'),
    (v_topic_id, 'A "Computerized Physician Order Entry" (CPOE) system primarily improves safety by:', '["Eliminating handwriting errors", "Allowing for automated dose checking and interaction alerts", "Improving the legibility of orders", "All of the above"]', 3, 'CPOE addresses many of the risks associated with manual paper-based ordering.'),
    (v_topic_id, 'What is "Alert Fatigue" in the context of an EHR?', '["The nurse being too tired to work", "Clinicians ignoring safety alerts because the system generates too many low-risk or irrelevant warnings", "The computer system crashing", "A patient being annoyed by beeping monitors"]', 1, 'Alert fatigue leads clinicians to "click through" even critical warnings.'),
    (v_topic_id, 'The best way to reduce alert fatigue is to:', '["Turn off all alerts", "Fine-tune the system so only clinically significant, high-risk alerts are displayed", "Require a signature for every alert", "Increase the volume of the alert sound"]', 1, 'Specific, actionable, and rare alerts are more likely to be respected.'),

    -- CARE COORDINATION REVISITED
    (v_topic_id, 'The "Patient-Centered Medical Home" (PCMH) model aims to improve safety through:', '["Fragmenting care into many small clinics", "Coordinated, team-based care led by a primary care provider", "Using only holistic medicine", "Reducing the number of doctors a patient sees"]', 1, 'Coordination reduces the "gaps" where errors occur during transitions.'),
    (v_topic_id, 'A "Care Transition" occurs when a patient moves from:', '["The ICU to the medical floor", "The hospital to a skilled nursing facility", "The clinic to their home", "All of the above"]', 3, 'Every move between settings or levels of care is a transition with associated risks.'),
    (v_topic_id, 'Which document is essential for a safe transition from the hospital to a nursing home?', '["The patient''s birth certificate", "A detailed Discharge Summary including the final diagnosis, med list, and follow-up plan", "The hospital''s annual report", "A list of the patient''s favorite foods"]', 1, 'The discharge summary is the "handoff" document between settings.'),
    (v_topic_id, 'In the "Swiss Cheese Model," if a pharmacist catches an error made by a resident, the pharmacist represents a __________.', '["Hole in the cheese", "Layer of defense (the cheese)", "Latent error", "Active failure"]', 1, 'Safety layers (defense in depth) are intended to catch errors before they reach the patient.'),
    (v_topic_id, 'Which of the following is a "Systems" reason for handoff errors?', '["A culture of \"don''t ask questions\"", "Lack of a quiet, uninterrupted space for handoffs", "Inconsistent electronic handoff tools", "All of the above"]', 3, 'Environmental and organizational factors (latent errors) are the primary drivers of handoff failure.'),

    -- MORE MEDICATION SAFETY
    (v_topic_id, 'What is the most common type of medical error in a hospital setting?', '["Surgical error", "Medication error", "Diagnostic error", "Infant abduction"]', 1, 'Medication errors are the most frequent type of safety incident, although not all result in harm.'),
    (v_topic_id, 'Which of the following is a "Preventive Error"?', '["Giving the wrong vaccine", "Failure to provide prophylactic treatment (e.g., VTE prophylaxis)", "Inadequate follow-up of a screening test", "All of the above"]', 3, 'Preventive errors are failures to provide appropriate preventive care.'),
    (v_topic_id, 'A "Look-Alike" drug error is more likely to happen if:', '["Drugs are stored alphabetically by generic name", "Drugs are stored by therapeutic class", "Drugs have standardized labels", "Drugs are kept in the pharmacy only"]', 0, 'Alphabetical storage can place similar-looking names (e.g., Prednisone and Prednisolone) right next to each other.'),
    (v_topic_id, 'The use of "Leading Zeros" (e.g., 0.5 mg) is recommended because:', '["It looks more scientific", "It prevents .5 mg from being read as 5 mg", "It saves space", "It is required by the FDA"]', 1, 'Leading zeros prevent a common source of 10-fold dosing errors.'),
    (v_topic_id, 'The use of "Trailing Zeros" (e.g., 5.0 mg) is DISCOURAGED because:', '["It takes too long to write", "It can be misread as 50 mg if the decimal point is missed", "It is mathematically incorrect", "It confuses the patient"]', 1, 'Trailing zeros are a "dangerous" practice in medical writing.'),

    -- FINAL MED SAFETY
    (v_topic_id, 'A "Pharmacy Intervention" occurs when a pharmacist:', '["Identifies a potential drug-related problem and recommends a change to the prescriber", "Fills a prescription exactly as written", "Charges a co-pay", "Organizes the medicine cabinet"]', 0, 'Interventions are active safety catches by the pharmacy team.'),
    (v_topic_id, 'What is a "Patient Safety Organization" (PSO)?', '["An insurance company", "An external body that collects and analyzes safety data to help providers improve care", "A group of patients who sue hospitals", "A marketing firm for medical devices"]', 1, 'PSOs provide a protected legal environment for sharing safety data and learning.'),
    (v_topic_id, 'The "I" in SBAR stands for "Introduction" in some versions, but the "A" ALWAYS stands for:', '["Action", "Assessment", "Always", "Appointment"]', 1, 'Assessment is the clinician''s synthesis of the situation.'),
    (v_topic_id, 'Which of the following is a strong strategy for reducing PCA (Patient-Controlled Analgesia) errors?', '["Allowing family members to press the button", "Using standardized order sets and independent double-checks for pump settings", "Hiding the pump in a closet", "Telling the patient to be careful"]', 1, 'PCA involves high-alert opioids and requires rigorous safety protocols.'),
    (v_topic_id, 'What is the "First Priority" after identifying that a patient received a medication they are allergic to?', '["Reporting to the FDA", "Immediate clinical assessment and stabilization of the patient", "Checking the medical record to see who made the error", "Filing a lawsuit"]', 1, 'Patient safety and stabilization always come first.')
END $$;
